style.css:
@-moz-document domain("discord.com") {
body {
    background: radial-gradient(circle, #003d99 0%, #001933 100%) !important;
    animation: bgPulse 10s ease-in-out infinite;
  }

  .appMount-3lHmkl {
    background: transparent !important;
  }

  .layers-3iHuyZ {
    background: transparent !important;
  }

  @keyframes bgPulse {
    0% {
      background: radial-gradient(circle, #003d99 0%, #001933 100%);
    }
    50% {
      background: radial-gradient(circle, #0044b3 0%, #001933 100%);
    }
    100% {
      background: radial-gradient(circle, #003d99 0%, #001933 100%);
    }
  }
}
